const {StringDecoder}=require('string_decoder');
const bytes=Buffer.from([0x78,0x41,0xe2,0x82,0xac,0x42,0x79,0x7a]);
const output=[];
for(const make of [b=>b.subarray(1,7),b=>new Int8Array(b.buffer,b.byteOffset+1,6),b=>new Uint16Array(b.buffer,b.byteOffset,4),b=>new DataView(b.buffer,b.byteOffset+1,6)]){
 for(const encoding of ['utf8','utf16le','latin1','ascii','hex','base64','base64url']){
  const decoder=new StringDecoder(encoding);output.push([encoding,decoder.write(make(bytes)),decoder.end()]);
 }
}
for(const view of [bytes.subarray(0,0),new DataView(bytes.buffer,bytes.byteOffset,0)]){const d=new StringDecoder();output.push([d.write(Buffer.from([0xe2])),d.write(view),d.end(Buffer.from([0x82,0xac]))]);}
console.log(JSON.stringify(output));
